        Check(resized.Left==screen.Left&&resized.Top==screen.Top,"top left screen clamp");
        Check(PanelGeometry.Resize(start,new Point(10,20),0,screen)==start,"no resize edge is inert");
        Check(PanelGeometry.Resize(start,new Point(10,20),2,screen).Height==start.Height,"horizontal resize preserves height");
