        speechClock.TogglePause(960);hold.Observe(speechClock,970,speechSession.File,themeMatch);
        StableExit(hold,speechClock,1000,speechSession.File,FileTiming.Match(meetingRules,480,bInfo));
        Check(speechClock.Paused&&speechClock.Elapsed(1100)==10,"manual pause preserved on return");
        speechSession.Start(speechClock,1100,aInfo,meetingRules,480);speechSession.Choose(speechClock,1105,new FileRule{File="custom",Seconds=600});
