        hold.Observe(speechClock,1500,"",themeMatch);hold.Clear();
        Check(!hold.Hidden,"background can be explicitly cleared");
        var backgroundWindow=new ShowInfo{Handle=new IntPtr(501),IsShow=true,Foreground=false,File=themeInfo.File};
        var speechWindow=new ShowInfo{Handle=new IntPtr(502),IsShow=true,Foreground=true,File=aInfo.File};
