            var old=(Settings)new System.Xml.Serialization.XmlSerializer(typeof(Settings)).Deserialize(reader);old.Normalize();
            Check(!old.Rules[0].Background&&old.Rules[0].Seconds==120,"legacy rules remain normal speeches");
        }
        var stableClock=new ClockState();var stableSession=new TimingSession();var stableHold=new BackgroundHold();
        stableSession.Start(stableClock,0,aInfo,meetingRules,480);
