        stableHold.Observe(stableClock,70,stableSession.File,FileTiming.Match(meetingRules,480,bInfo));
        Check(stableHold.Observe(stableClock,70.1,stableSession.File,FileTiming.Match(meetingRules,480,bInfo))==1,"two rapid reads do not meet stability interval");
