        Check(!stableClock.Paused&&stableClock.Elapsed(110)==10,"off/on resumes running speech without losing elapsed time");
        stableClock.TogglePause(115);stableHold.Observe(stableClock,116,stableSession.File,themeMatch);stableHold.SuspendMonitoring();stableHold.ResumeMonitoring();
        StableExit(stableHold,stableClock,120,stableSession.File,FileTiming.Match(meetingRules,480,aInfo));
        Check(stableClock.Paused,"off/on does not undo pre-existing manual pause");
