        Check(show.File=="Talk4.pptx","owner window association");
        resolver=new WindowFiles();show=new ShowInfo{Handle=new IntPtr(30),ProcessId=20,Process="wpp",IsShow=true};
        resolver.Enrich(new List<ShowInfo>{show,new ShowInfo{Handle=new IntPtr(10),ProcessId=20,Title="Talk5.pptx - WPS 演示"}},new List<ShowInfo>(),many,1);
        Check(show.File=="Talk5.pptx","unique same-process document association");
        resolver=new WindowFiles();show=new ShowInfo{Handle=new IntPtr(30),ProcessId=20,Process="wpp",IsShow=true};
        resolver.Enrich(new List<ShowInfo>{show,new ShowInfo{Handle=new IntPtr(10),ProcessId=20,Title="Talk5.pptx - WPS 演示"},new ShowInfo{Handle=new IntPtr(11),ProcessId=20,Title="Talk6.pptx - WPS 演示"}},new List<ShowInfo>(),many,1);
        Check(show.File=="","multiple document windows are not guessed");
        resolver=new WindowFiles();show=new ShowInfo{Handle=new IntPtr(30),ProcessId=20,Process="wpp",IsShow=true};
        resolver.Enrich(new List<ShowInfo>{show,new ShowInfo{Handle=new IntPtr(10),ProcessId=21,Title="Talk5.pptx - WPS 演示"}},new List<ShowInfo>(),many,1);
        Check(show.File=="","different process cannot supply document identity");
        resolver=new WindowFiles();show=new ShowInfo{Handle=new IntPtr(30),ProcessId=20,Process="wpp",IsShow=true};
        resolver.Enrich(new List<ShowInfo>{show},new List<ShowInfo>{new ShowInfo{Handle=new IntPtr(30),File=@"D:\Meetings\Talk6.pptx",Page=0}},many,1);
        Check(show.File==@"D:\Meetings\Talk6.pptx","COM filename is usable without page number");
        resolver=new WindowFiles();show=new ShowInfo{Handle=new IntPtr(30),ProcessId=20,Process="wpp",IsShow=true};
        resolver.Enrich(new List<ShowInfo>{show},new List<ShowInfo>{new ShowInfo{Process="wpp",File=@"D:\Meetings\Talk7.pptx"}},many,1);
        Check(show.File==@"D:\Meetings\Talk7.pptx","COM without HWND associates only unique slideshow");
        resolver=new WindowFiles();show=new ShowInfo{Handle=new IntPtr(30),ProcessId=20,Process="wpp",IsShow=true};
        resolver.Enrich(new List<ShowInfo>{show,new ShowInfo{Handle=new IntPtr(31),ProcessId=21,Process="wpp",IsShow=true}},new List<ShowInfo>{new ShowInfo{Process="wpp",File=@"D:\Meetings\Talk7.pptx"}},many,1);
        Check(show.File=="","COM without HWND does not guess among simultaneous slideshows");
        Check(OfficeProbe.ReadWindow(new PartialOfficeWindow(),"wpp").File==@"C:\Meetings\Report.pptx","optional COM properties cannot discard FullName");
        Check(OfficeProbe.ReadWindow(new NamedOfficeWindow(),"wpp").File=="Named.pptx","COM Name fallback when FullName unavailable");
        string decision;
        var monitor=new Rectangle(0,0,1920,1080);
        var pdf=new ShowInfo{Process="Acrobat",Title="Report.pdf - Adobe Acrobat",Visible=true,Caption=true,ClientValid=true,MonitorBounds=monitor,ClientBounds=monitor,WindowBounds=new Rectangle(-16,-16,1952,1112)};
        Check(FullscreenPolicy.Evaluate(pdf,true,out decision),"Acrobat full client with retained caption and invisible borders");
        Check(decision.StartsWith("PDF 全屏"),"PDF detection reason is explicit");
        pdf.Process="AcroRd32";Check(FullscreenPolicy.Evaluate(pdf,false,out decision),"Reader full screen does not require generic compatibility option");
        pdf.ClientBounds=new Rectangle(0,31,1920,1009);pdf.WindowBounds=new Rectangle(-8,-8,1936,1056);
        Check(!FullscreenPolicy.Evaluate(pdf,true,out decision),"ordinary maximized Reader window is not full screen");
        pdf.WindowBounds=monitor;pdf.ClientBounds=new Rectangle(0,32,1920,1048);
        Check(!FullscreenPolicy.Evaluate(pdf,true,out decision),"full outer frame with visible title area is not full screen");
        pdf.WindowBounds=new Rectangle(100,100,1200,800);pdf.ClientBounds=new Rectangle(100,130,1200,770);
        Check(!FullscreenPolicy.Evaluate(pdf,true,out decision),"windowed PDF is not full screen");
        pdf.WindowBounds=monitor;pdf.ClientBounds=monitor;pdf.Minimized=true;
        Check(!FullscreenPolicy.Evaluate(pdf,true,out decision),"minimized PDF never starts timer");
        pdf.Minimized=false;pdf.Visible=false;
        Check(!FullscreenPolicy.Evaluate(pdf,true,out decision),"hidden PDF never starts timer");
        pdf.Visible=true;pdf.ClientValid=false;
        Check(!FullscreenPolicy.Evaluate(pdf,true,out decision),"unknown client area with caption is not guessed");
        pdf.Caption=false;
        Check(FullscreenPolicy.Evaluate(pdf,false,out decision),"borderless PDF fallback without client geometry");
        pdf.Caption=true;pdf.ClientValid=true;pdf.Process="wps";
        Check(FullscreenPolicy.Evaluate(pdf,false,out decision),"unified WPS process can host full-screen PDF");
        pdf.Title="Report.pptx - WPS 演示";
        Check(!FullscreenPolicy.Evaluate(pdf,true,out decision),"unified WPS full-size editing window is not assumed to be PDF");
        pdf.Process="wpp";pdf.Title="WPS Presentation Slide Show -［Report.pptx］";
        Check(FullscreenPolicy.Evaluate(pdf,false,out decision),"explicit WPS presentation detection remains supported");
        pdf.Process="Acrobat";pdf.Title="Report.pdf - Adobe Acrobat";pdf.MonitorBounds=new Rectangle(-2560,0,2560,1440);pdf.ClientBounds=pdf.MonitorBounds;pdf.WindowBounds=new Rectangle(-2576,-16,2592,1472);
        Check(FullscreenPolicy.Evaluate(pdf,true,out decision),"secondary monitor negative coordinates and larger borders");
        Check(FileTiming.Resolve(new List<FileRule>{new FileRule{File=@"C:\Meetings\Report.pdf",Seconds=720}},480,new ShowInfo{Title="Report - Adobe Acrobat Pro DC (64-bit)"})==720,"Adobe caption without extension uses dedicated PDF duration");
        foreach(bool final in new[]{false,true}){
            using(var stream=Audio.Wave(final))using(var reader=new BinaryReader(stream)){
                Check(new string(reader.ReadChars(4))=="RIFF","WAV RIFF header");
                Check(reader.ReadInt32()==stream.Length-8,"WAV container length");
                Check(new string(reader.ReadChars(8))=="WAVEfmt ","WAV format header");
                Check(reader.ReadInt32()==16&&reader.ReadInt16()==1&&reader.ReadInt16()==1,"PCM mono");
                Check(reader.ReadInt32()==22050&&reader.ReadInt32()==44100,"sample rate");
                Check(reader.ReadInt16()==2&&reader.ReadInt16()==16,"16 bit samples");
                Check(new string(reader.ReadChars(4))=="data","WAV data header");
                int length=reader.ReadInt32();Check(length==stream.Length-44&&length>22050,"WAV audio payload");
            }
        }
        Console.WriteLine("PASS: "+checks+" regression checks.");return 0;
    }
}
